INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted, reviewed) VALUES (38, '数学', '二年级', '填空', 2, '{"stem": "一张100元可以换（ ）张50元和（ ）张10元。", "options": null}', '1，5', '100=50×1+10×5，1张50元和5张10元。', 'paper', '["拓展卷", "U2"]', '["paper_png/yg2_sx/p017"]', 0, 1);
